sparql_coverage.query:
PREFIX p: <https://hswm.invalid/kg-bundle-rdf/v1/prop/>
PREFIX r: <https://hswm.invalid/kg-bundle-rdf/v1/rel/>
SELECT ?family ?method ?theory ?gap WHERE {
 ?f p:standard_graph_role "RESEARCH_TECHNIQUE_FAMILY"; p:name ?family;
    r:HAS_SOURCE/p:source_id ?method.
 OPTIONAL { ?f r:HAS_MATHEMATICAL_CONNECTION/p:source_id ?theory. }
 OPTIONAL { ?f r:INFORMS_HYPOTHESIS/r:ADDRESSES ?gap. }
} ORDER BY ?family ?method ?theory ?gap
